questiontext.text:
Consider the function \(f(x)=\tan x\) on the interval \(-\pi<x<\pi\).

Use the graph to help you identify the period of the function.

[[jsxgraph]]
var board = JXG.JSXGraph.initBoard(divid, {
    boundingbox: [-3.5, 4, 3.5, -4],
    axis: true,
    showCopyright: false,
    keepAspectRatio: false
});

board.create('functiongraph', [
    function(x) { return Math.tan(x); },
    -Math.PI + 0.05, -Math.PI/2 - 0.08
], {strokeWidth: 2});

board.create('functiongraph', [
    function(x) { return Math.tan(x); },
    -Math.PI/2 + 0.08, Math.PI/2 - 0.08
], {strokeWidth: 2});

board.create('functiongraph', [
    function(x) { return Math.tan(x); },
    Math.PI/2 + 0.08, Math.PI - 0.05
], {strokeWidth: 2});

board.create('line', [[-Math.PI/2, -4], [-Math.PI/2, 4]], {
    dash: 2, strokeColor: '#C0392B'
});

board.create('line', [[Math.PI/2, -4], [Math.PI/2, 4]], {
    dash: 2, strokeColor: '#C0392B'
});
[[/jsxgraph]]

1. Period

What is the period of the function?

[[input:ans_period]]
[[validation:ans_period]][[feedback:prt1]]

questionvariables.text:
/* Question 1: Period of the tangent function */

/* Define the function */
f(x) := tan(x);

/* Expected period */
ta_period: %pi;
